{"type":"item.completed","item":{"id":"item_1","type":"agent_message","text":"{\"tool\":\"sql_query\",\"arguments\":{\"company_name\":\"CLOSE_fin_06\",\"table_name\":\"ledger\",\"query\":\"WITH ranked AS (SELECT kind,event_key,invoice_id,vendor,business_date,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den,ROW_NUMBER() OVER (PARTITION BY kind,event_key ORDER BY revision DESC) AS rn FROM ledger WHERE business_date<='2026-10-23' AND datetime(recorded_at)<=datetime('2026-10-24T12:00:00')), active AS (SELECT kind,event_key,invoice_id,vendor,business_date,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den FROM ranked WHERE rn=1 AND status<>'void'), balances AS (SELECT i.event_key,i.business_date,i.currency,i.discount_until,i.terms_code,MAX(0,MAX(0,i.amount_minor-COALESCE((SELECT SUM(p.amount_minor) FROM active p WHERE p.kind='payment' AND p.invoice_id=i.event_key),0)-COALESCE((SELECT SUM(c.amount_minor) FROM active c WHERE c.kind='credit' AND c.invoice_id=i.event_key),0))-COALESCE((SELECT SUM(h.amount_minor) FROM active h WHERE h.kind='hold' AND h.status='active' AND h.invoice_id=i.event_key),0)) AS unheld FROM active i WHERE i.kind='invoice' AND i.vendor='BLUE' AND i.due_date<='2026-10-30'), fractions AS (SELECT b.event_key,b.unheld*(CASE WHEN b.discount_until>='2026-10-23' THEN 10000-t.discount_bps ELSE 10000 END)*f.fx_num AS numerator,10000*f.fx_den AS denominator FROM balances b JOIN active t ON t.kind='terms' AND t.event_key=(SELECT tt.event_key FROM active tt WHERE tt.kind='terms' AND tt.terms_code=b.terms_code AND tt.business_date<=b.business_date ORDER BY tt.business_date DESC LIMIT 1) JOIN active f ON f.kind='fx' AND f.event_key=(SELECT ff.event_key FROM active ff WHERE ff.kind='fx' AND ff.currency=b.currency AND ff.business_date<=b.business_date ORDER BY ff.business_date DESC LIMIT 1)), rounded AS (SELECT event_key,CAST(numerator/denominator AS INTEGER)+CASE WHEN 2*(numerator%denominator)>=denominator THEN 1 ELSE 0 END AS usd_cents FROM fractions WHERE denominator>0) SELECT event_key,usd_cents,SUM(usd_cents) OVER () AS total_usd_cents FROM rounded WHERE 1=1 ORDER BY event_key\"}}"}}
